CREATE TABLE IF NOT EXISTS employee_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, request_type text NOT NULL, title text NOT NULL, details text, status text NOT NULL DEFAULT 'pending', manager_id uuid, reviewed_at timestamptz, reviewer_note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid REFERENCES people_records(id) ON DELETE CASCADE, alert_type text NOT NULL, severity text NOT NULL DEFAULT 'info', due_date date, title text NOT NULL, details text, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_cycles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, due_date date, status text NOT NULL DEFAULT 'planned', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_requests_person_status ON employee_requests(person_id,status); CREATE INDEX IF NOT EXISTS idx_alerts_status_due ON employee_alerts(status,due_date);